  createdAt: z.string(),
})
export const ExportFormat = z.enum(['json', 'csv'])
export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({ format: ExportFormat.default('json') }),
  output: 'response',
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

'''
s=s.replace(old,new)
