p='features/notes/server.ts'
s=open(p).read()
old=s[s.index("    implement(exportNotes,"):s.index("    implement(getNote,")]
new='''    implement(exportNotes, ({ format }, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const items = listOf(session)
      const notes = [...items.filter((item) => item.pinned), ...items.filter((item) => !item.pinned)].map((item) => ({
        number: item.number,
        title: item.title,
        body: item.body.replace(/\\r\\n?/g, '\\n'),
        pinned: item.pinned,
        archived: item.archived,
        createdAt: new Date(item.createdAt).toISOString(),
      }))
      const download = (type: string, ext: string) => ({
        'content-type': type,
        'content-disposition': `attachment; filename="notes-${session.user}.${ext}"`,
      })
      if (format === 'csv') {
        const lines = [CSV_COLUMNS.join(','), ...notes.map((note) => CSV_COLUMNS.map((key) => csvValue(String(note[key]))).join(','))]
        return new Response(lines.map((line) => `${line}\\r\\n`).join(''), { status: 200, headers: download('text/csv; charset=utf-8', 'csv') })
      }
      return new Response(JSON.stringify({ user: session.user, notes }), { status: 200, headers: download('application/json; charset=utf-8', 'json') })
    }),
'''
s=s.replace(old,new)
